#!/usr/bin/env python3
"""manual skip_stuck_marks: same as skip_stuck_marks.py but hdfs without sudo (run as hadoop)."""
import json, subprocess, sys, datetime as dt, os, shutil

DRY = "--dry" in sys.argv  # keep false for live; we control via env
DRY = os.environ.get("SKIP_DRY", "0") == "1"
LOOKBACK_H = 96
H = "/opt/bigdata/hadoop-3.3.6/bin/hdfs"
BASE = "/user/hadoop/etl_state/state/pipeline_runner"
STEPS = "/home/ec2-user/pipeline-runner/steps/full_chain.json"
NOW = dt.datetime.now()
HOUR_CUT = NOW.replace(minute=0, second=0, microsecond=0) - dt.timedelta(hours=1)
TODAY = NOW.date()

def hdfs(*a, inp=None):
    return subprocess.run([H, "dfs", *a], input=inp, capture_output=True, text=True)

plan = json.load(open(STEPS))
unit = {s["name"]: s.get("unit", "day") for s in plan["steps"]}
group_steps = {g: v.get("steps", []) for g, v in plan["groups"].items()}
slots_of = {}
for hh, items in plan["slots"].items():
    for it in items:
        n = (it.get("step") or it.get("group")) if isinstance(it, dict) else it
        for s in (group_steps[n] if n in group_steps else [n]):
            if s in unit:
                slots_of.setdefault(s, set()).add(int(hh))

want = {}
for step, hhs in slots_of.items():
    t = NOW.replace(minute=0, second=0, microsecond=0) - dt.timedelta(hours=LOOKBACK_H)
    while t <= NOW:
        if t.hour in hhs:
            if unit[step] == "hour" and t < HOUR_CUT:
                d = t - dt.timedelta(hours=1)
                want[(step, f"{d:%Y-%m-%dT%H}#{t.hour:02d}")] = 1
            elif unit[step] != "hour" and t.date() < TODAY:
                want[(step, f"{t.date() - dt.timedelta(days=1)}#{t.hour:02d}")] = 1
        t += dt.timedelta(hours=1)

keys = sorted({k for _, k in want})
status = {}
# batch ls in chunks to avoid arg max
present = set()
for i in range(0, len(keys), 50):
    chunk = keys[i:i+50]
    ls = hdfs("-ls", *[f"{BASE}/{k}" for k in chunk])
    for l in ls.stdout.splitlines():
        if l.endswith(".json"):
            present.add(l.split()[-1][len(BASE) + 1:])
need_read = [f"{BASE}/{k}/{s}.json" for s, k in want if f"{k}/{s}.json" in present]
for i in range(0, len(need_read), 200):
    out = hdfs("-cat", *need_read[i:i + 200]).stdout
    for line in out.replace("}{", "}\n{").splitlines():
        try:
            n = json.loads(line)
            status[(n.get("step"), n.get("dt"))] = n.get("status")
        except ValueError:
            pass

todo = [(s, k) for s, k in sorted(want, key=lambda x: x[1])
        if f"{k}/{s}.json" not in present or status.get((s, k)) not in ("SUCCESS", "SKIPPED", "RUNNING")]
stamp = NOW.strftime("%Y-%m-%d %H:%M:%S")
STAGE = f"/home/ec2-user/pipeline-runner/testcluster/.skip_stage_{NOW:%Y%m%d%H%M%S}"
by_key = {}
# print summary samples
print(f"present_marks={len(present)} want={len(want)} todo={len(todo)}")
for s, k in todo[:30]:
    prev = status.get((s, k)) if f"{k}/{s}.json" in present else None
    print(f"{'DRY ' if DRY else ''}SKIP {k:<20} {s:<48} 原状态={prev}")
if len(todo) > 30:
    print(f"... and {len(todo)-30} more")
for s, k in todo:
    by_key.setdefault(k, []).append(s)
if not DRY and todo:
    for k, steps in by_key.items():
        os.makedirs(f"{STAGE}/{k.replace('#', '__')}", exist_ok=True)
        for s in steps:
            body = {"step": s, "dt": k, "status": "SKIPPED", "rc": 0, "fail_count": 0,
                    "pipeline": "pipeline_runner", "host": "manual", "skipped_ts": stamp,
                    "msg": "测试不追历史: skip_stuck_marks.py 置 SKIPPED 放行到当前时间(知秋 10-29)"}
            with open(f"{STAGE}/{k.replace('#', '__')}/{s}.json", "w") as f:
                json.dump(body, f, ensure_ascii=False)
    # hadoop already owns
    hdfs("-mkdir", "-p", *[f"{BASE}/{k}" for k in by_key])
    fail = 0
    for k, steps in by_key.items():
        r = hdfs("-put", "-f", *[f"{STAGE}/{k.replace('#', '__')}/{s}.json" for s in steps], f"{BASE}/{k}/")
        if r.returncode != 0:
            fail += 1
            print(f"   写失败 {k}:", r.stderr.strip()[:300])
    shutil.rmtree(STAGE)
    print(f"write_fail_dirs={fail}")
print(f"{stamp} 扫 {len(want)} 格, 置 SKIPPED {len(todo)} 格, {len(by_key)} 个目录 DRY={DRY}")
